// приводим письма из IMAP к простому виду {from, subject, text}
return $input.all().map(i => ({ json: {
  from: (i.json.from && i.json.from.value && i.json.from.value[0] && i.json.from.value[0].address) || String(i.json.from || ''),
  subject: i.json.subject || '(без темы)',
  text: String(i.json.textPlain || i.json.textHtml || '').slice(0, 2000),
}}));

// набор тестовых писем для проверки конвейера без реального ящика
const mails = [
  {
    from: 'prize@super-lottery.win',
    subject: 'ПОЗДРАВЛЯЕМ! Вы выиграли iPhone 17 Pro!!!',
    text: 'Ваш адрес был выбран случайным образом! Заберите приз в течение 24 часов, иначе он сгорит. Перейдите по ссылке и оплатите доставку 299 руб: http://super-lottery.win/claim'
  },
  {
    from: 'shishkin.vv@ulstu.ru',
    subject: 'Отчёты по лабораторной работе',
    text: 'Добрый день. Напоминаю, что отчёт по четвёртой лабораторной работе нужно прислать сегодня до 18:00. Работы, присланные позже, будут проверяться в следующем семестре.'
  },
  {
    from: 'starosta@ulstu.ru',
    subject: 'Созвон по курсовым в четверг',
    text: 'Всем привет! В четверг в 15:00 собираемся в дискорде обсудить курсовые проекты. Кто не сможет — отпишитесь заранее, перенесём.'
  },
  {
    from: 'digest@habr.com',
    subject: 'Хабр: лучшие публикации за неделю',
    text: 'В этом выпуске: сравнение локальных LLM для слабых видеокарт, обзор n8n против Zapier, история одного бага в планировщике Go. Читайте на сайте.'
  },
  {
    from: 'security@sberbank-verify.info',
    subject: 'Ваша карта заблокирована',
    text: 'Уважаемый клиент! Ваша карта была заблокирована в целях безопасности. Для разблокировки срочно подтвердите данные карты по ссылке: http://sberbank-verify.info/unlock'
  }
];
return mails.map(m => ({ json: m }));

// каждое письмо прогоняем через локальную модель pochta-analitik
const out = [];
for (const item of $input.all()) {
  const mail = item.json;
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:11434/api/generate',
    body: {
      model: 'pochta-analitik',
      prompt: 'Отправитель: ' + mail.from + '\nТема: ' + mail.subject + '\nТекст письма:\n' + mail.text,
      stream: false,
      format: 'json',
      options: { temperature: 0.2 }
    },
    json: true,
    timeout: 180000,
  });
  let verdict;
  try {
    verdict = JSON.parse(resp.response);
  } catch (e) {
    verdict = { spam: false, category: 'К сведению', summary: 'не удалось разобрать ответ модели', action: 'посмотреть письмо вручную' };
  }
  out.push({ json: Object.assign({}, mail, verdict) });
}
return out;

// группируем письма по категориям и собираем markdown-дайджест
const order = ['Срочно', 'Встречи', 'К сведению', 'Спам'];
const mails = $input.all().map(i => i.json);

const lines = [];
lines.push('# Почтовый дайджест — ' + new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Ulyanovsk' }));
lines.push('');
lines.push('Всего писем: ' + mails.length + ', из них спам: ' + mails.filter(m => m.spam).length);
lines.push('');

for (const cat of order) {
  const group = mails.filter(m => (m.spam ? 'Спам' : m.category) === cat);
  if (!group.length) continue;
  lines.push('## ' + cat + ' (' + group.length + ')');
  lines.push('');
  for (const m of group) {
    lines.push('- **' + m.subject + '** — от ' + m.from);
    lines.push('  Выжимка: ' + m.summary);
    // для спама совет модели не нужен, там всегда одно действие
    lines.push('  Действие: ' + (m.spam ? 'не открывать, удалить' : m.action));
  }
  lines.push('');
}

const text = lines.join('\n');
const stamp = new Date().toISOString().slice(0, 19).replace('T', '_').split(':').join('-');

return [{
  json: { fileName: '/data/output/digest_' + stamp + '.md' },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), 'digest.md', 'text/markdown') }
}];
